// Builds the outputs of the design tokens in memory: the single place that
// knows Style Dictionary. `build-tokens.mjs` writes what this returns, and the
// tests compare it with the committed files, so a hand edit of a generated
// file cannot survive. Knows nothing about the CSS that uses the tokens.

import StyleDictionary from 'style-dictionary';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const header = [
  'Generated by scripts/build-tokens.mjs from tokens/*.tokens.json.',
  'Do not edit: change the tokens and run `npm run tokens`.',
];

function config() {
  return {
    // Style Dictionary globs the source, and a glob wants forward slashes
    // even on Windows.
    source: [path.join(root, 'tokens', '*.tokens.json').replaceAll('\\', '/')],
    usesDtcg: true,
    log: { verbosity: 'silent', warnings: 'error' },
    hooks: {
      fileHeaders: { kanshi: () => header },
      transforms: {
        // TODO: drop when style-dictionary is raised to 5.7.0 or later, which
        // reads DTCG 2025.10 durations itself; 5.6.1 prints "[object Object]".
        'kanshi/duration': {
          type: 'value',
          filter: (token) => token.$type === 'duration' && typeof token.$value === 'object',
          transform: (token) => `${token.$value.value}${token.$value.unit}`,
        },
      },
    },
    platforms: {
      css: {
        transformGroup: 'css',
        transforms: ['kanshi/duration'],
        prefix: 'k',
        buildPath: 'src/',
        files: [
          {
            destination: 'tokens.css',
            format: 'css/variables',
            // The palette stays in the token source for tools that read it,
            // but not in the CSS: components reach colors only through roles.
            filter: (token) => token.path[0] !== 'palette',
            options: { fileHeader: 'kanshi', outputReferences: false },
          },
        ],
      },
    },
  };
}

/** @returns {Promise<{ destination: string, output: string }[]>} paths relative to the repo root */
export async function buildTokenFiles() {
  const dictionary = new StyleDictionary(config());
  const files = await dictionary.formatPlatform('css');
  return files.map(({ destination, output }) => ({
    destination: path.relative(root, path.resolve(root, destination)).replaceAll('\\', '/'),
    output: String(output),
  }));
}

export { root };
